UPDATE news_articles SET body = REPLACE(body,
    '<ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Diversificazione istantanea</strong> — un solo acquisto ti espone a centinaia o migliaia di società contemporaneamente, senza dover scegliere quali comprare una per una.</li><li><strong>Costi bassi</strong> — la maggior parte degli ETF è gestita passivamente (replica un indice invece di far scegliere i titoli a un gestore), il che tiene i costi annui molto più bassi rispetto a un fondo a gestione attiva.</li><li><strong>Trasparenza</strong> — sai sempre esattamente cosa contiene, perché replica un indice pubblico e verificabile, non le scelte discrezionali di un gestore.</li></ul>',
    '<ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Diversificazione istantanea</strong> — un solo acquisto ti espone a centinaia o migliaia di società contemporaneamente, senza dover scegliere quali comprare una per una.</li><li><strong>Costi bassi</strong> — la maggior parte degli ETF è gestita passivamente (replica un indice invece di far scegliere i titoli a un gestore), il che tiene i costi annui molto più bassi rispetto a un fondo a gestione attiva.</li><li><strong>Trasparenza</strong> — sai sempre esattamente cosa contiene, perché replica un indice pubblico e verificabile, non le scelte discrezionali di un gestore.</li></ul><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">10.000 euro per 20 anni: quanto pesano i costi (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5"></th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Costo annuo</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Capitale finale</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Fondo a gestione attiva</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">1,5%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">24.117</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">ETF a gestione passiva</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">0,2%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">30.883</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Stesso rendimento lordo ipotetico del 6% annuo per entrambi: la differenza, circa 6.765 euro, è solo l''effetto dei costi. Tasse e commissioni del broker escluse.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'cosa-e-un-etf-guida-per-principianti' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Imposti un importo (es. 200&euro;) e una cadenza (es. il 5 di ogni mese). A ogni scadenza, quell''importo compra automaticamente quote dell''ETF scelto al prezzo di quel momento — a volte più alto, a volte più basso. Nel tempo, questo genera un effetto chiamato <strong>dollar-cost averaging</strong> (mediazione del costo): compri più quote quando il prezzo è basso e meno quote quando il prezzo è alto, il che abbassa il prezzo medio di carico rispetto a investire tutto insieme in un momento potenzialmente sbagliato.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Imposti un importo (es. 200&euro;) e una cadenza (es. il 5 di ogni mese). A ogni scadenza, quell''importo compra automaticamente quote dell''ETF scelto al prezzo di quel momento — a volte più alto, a volte più basso. Nel tempo, questo genera un effetto chiamato <strong>dollar-cost averaging</strong> (mediazione del costo): compri più quote quando il prezzo è basso e meno quote quando il prezzo è alto, il che abbassa il prezzo medio di carico rispetto a investire tutto insieme in un momento potenzialmente sbagliato.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">200 euro al mese per 6 mesi: quante quote compri</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Mese</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Prezzo della quota (€)</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Quote comprate</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">1° mese</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">50,00</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">4,00</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">2° mese</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">40,00</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">5,00</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">3° mese</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">25,00</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">8,00</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">4° mese</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">40,00</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">5,00</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">5° mese</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">50,00</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">4,00</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">6° mese</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">50,00</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">4,00</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5 font-semibold text-gray-900">Totale</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono font-semibold text-gray-900"></td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono font-semibold text-gray-900">30,00</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Prezzo medio del periodo: 42,50 euro. Prezzo medio pagato con il PAC: 40,00 euro, più basso perché nei mesi a prezzo basso compri più quote. Prezzi di esempio.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'pac-piano-accumulo-etf-come-funziona' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Avere 15 azioni tecnologiche americane non è diversificazione reale: sono 15 scommesse molto correlate tra loro, che tendono a salire e scendere insieme. Diversificazione reale significa combinare asset class, aree geografiche e settori che reagiscono diversamente agli stessi eventi economici — un modo semplice ed efficiente per farlo, per chi non vuole selezionare titoli singoli, è un ETF ampiamente diversificato che replica un intero mercato globale.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Avere 15 azioni tecnologiche americane non è diversificazione reale: sono 15 scommesse molto correlate tra loro, che tendono a salire e scendere insieme. Diversificazione reale significa combinare asset class, aree geografiche e settori che reagiscono diversamente agli stessi eventi economici — un modo semplice ed efficiente per farlo, per chi non vuole selezionare titoli singoli, è un ETF ampiamente diversificato che replica un intero mercato globale.</p><figure class="my-6 rounded-xl border border-border bg-white p-5"><figcaption class="mb-4 text-sm font-semibold text-gray-900">Se un titolo perde il 50%, quanto perde il portafoglio</figcaption><div class="space-y-3"><div><div class="mb-1 flex justify-between gap-3 text-sm"><span class="text-gray-700">1 titolo</span><span class="whitespace-nowrap font-mono text-gray-900">−50,0%</span></div><div class="h-2.5 rounded-full bg-gray-100"><div class="h-2.5 rounded-full bg-expense" style="width:100.0%"></div></div></div><div><div class="mb-1 flex justify-between gap-3 text-sm"><span class="text-gray-700">5 titoli</span><span class="whitespace-nowrap font-mono text-gray-900">−10,0%</span></div><div class="h-2.5 rounded-full bg-gray-100"><div class="h-2.5 rounded-full bg-expense" style="width:20.0%"></div></div></div><div><div class="mb-1 flex justify-between gap-3 text-sm"><span class="text-gray-700">20 titoli</span><span class="whitespace-nowrap font-mono text-gray-900">−2,5%</span></div><div class="h-2.5 rounded-full bg-gray-100"><div class="h-2.5 rounded-full bg-expense" style="width:5.0%"></div></div></div><div><div class="mb-1 flex justify-between gap-3 text-sm"><span class="text-gray-700">ETF globale, oltre 1.000 titoli</span><span class="whitespace-nowrap font-mono text-gray-900">−0,05%</span></div><div class="h-2.5 rounded-full bg-gray-100"><div class="h-2.5 rounded-full bg-expense" style="width:1.0%"></div></div></div></div><p class="mt-4 text-xs text-muted">Portafoglio diviso in parti uguali, altri titoli fermi. Attenzione: se i titoli sono correlati, quando uno scende tendono a scendere anche gli altri, e il vantaggio si riduce.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'diversificazione-portafoglio-cosa-significa-davvero' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">In entrambi i casi la tassazione italiana sulle plusvalenze e sui dividendi è la stessa aliquota, ma cambia <strong>quando</strong> si paga: con la distribuzione, l''imposta si applica a ogni stacco di dividendo lungo il percorso; con l''accumulazione, l''intero guadagno (incluso quello generato dai dividendi reinvestiti) viene tassato tutto insieme al momento della vendita — <a href="/news/tassazione-investimenti-etf-azioni-italia" class="text-accent hover:underline font-medium">ne parliamo nel dettaglio qui</a>.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">In entrambi i casi la tassazione italiana sulle plusvalenze e sui dividendi è la stessa aliquota, ma cambia <strong>quando</strong> si paga: con la distribuzione, l''imposta si applica a ogni stacco di dividendo lungo il percorso; con l''accumulazione, l''intero guadagno (incluso quello generato dai dividendi reinvestiti) viene tassato tutto insieme al momento della vendita — <a href="/news/tassazione-investimenti-etf-azioni-italia" class="text-accent hover:underline font-medium">ne parliamo nel dettaglio qui</a>.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">10.000 euro per 20 anni: accumulazione o distribuzione (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5"></th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Valore finale</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Netto dopo la vendita</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">ETF ad accumulazione</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">32.071</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">26.333</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">ETF a distribuzione, dividendi reinvestiti</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">29.067</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">25.449</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Esempio: prezzo +4% l''anno e dividendi del 2%, tasse al 26%. Con la distribuzione i dividendi sono tassati ogni anno e si reinveste solo il netto: alla fine circa 884 euro in meno. Bollo e commissioni esclusi.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'etf-accumulazione-o-distribuzione-differenze' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un TER dello 0,07% e uno dello 0,30% sullo stesso indice sembrano quasi uguali guardando i due numeri isolati. Ma su un capitale di 50.000€ investito per 20 anni a un rendimento lordo del 7% annuo, quella differenza di 0,23 punti percentuali l''anno si traduce in diverse migliaia di euro in meno a fine periodo per l''ETF più costoso — lo stesso principio dell''<a href="/news/interesse-composto-esempi-reali" class="text-accent hover:underline font-medium">interesse composto</a>, ma che questa volta lavora contro di te invece che a tuo favore.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un TER dello 0,07% e uno dello 0,30% sullo stesso indice sembrano quasi uguali guardando i due numeri isolati. Ma su un capitale di 50.000€ investito per 20 anni a un rendimento lordo del 7% annuo, quella differenza di 0,23 punti percentuali l''anno si traduce in diverse migliaia di euro in meno a fine periodo per l''ETF più costoso — lo stesso principio dell''<a href="/news/interesse-composto-esempi-reali" class="text-accent hover:underline font-medium">interesse composto</a>, ma che questa volta lavora contro di te invece che a tuo favore.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">50.000 euro per 20 anni al 7% lordo: l''effetto del TER (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">TER</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Capitale finale</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Rispetto al TER 0,07%</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">0,07%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">190.968</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">—</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">0,20%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">186.378</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">−4.590</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">0,30%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">182.919</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">−8.050</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">0,50%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">176.182</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">−14.786</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Il TER è sottratto ogni anno dal rendimento. Tasse, bollo e commissioni esclusi.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'ter-costi-etf-quanto-incidono-sul-rendimento' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un ETF che investe in titoli di Stato italiani gode di un trattamento fiscale misto: la quota di rendimento riconducibile ai titoli di Stato è tassata al 12,5%, il resto al 26% — il broker o la banca gestiscono questo calcolo automaticamente, non serve farlo a mano.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un ETF che investe in titoli di Stato italiani gode di un trattamento fiscale misto: la quota di rendimento riconducibile ai titoli di Stato è tassata al 12,5%, il resto al 26% — il broker o la banca gestiscono questo calcolo automaticamente, non serve farlo a mano.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Su 1.000 euro di guadagno, quanto resta (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Strumento</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Aliquota</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Tasse</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Netto</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Azioni, ETF, obbligazioni societarie</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">26%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">260</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">740</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Titoli di Stato italiani e white list</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">12,5%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">125</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">875</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">ETF con metà titoli di Stato</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">mista</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">192</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">808</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Esempio dell''ETF misto: metà del guadagno al 26% e metà al 12,5%. In più si paga l''imposta di bollo dello 0,2% annuo sul valore detenuto.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'tassazione-investimenti-etf-azioni-italia' AND body NOT LIKE '%<figure%';

