UPDATE news_articles SET body = REPLACE(body,
    '<ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Ribilanciamento a calendario</strong> — un controllo a intervalli fissi (ad esempio una volta l''anno), indipendentemente da quanto si sono mosse le percentuali.</li><li><strong>Ribilanciamento a soglia</strong> — si interviene solo quando una asset class si discosta dal target oltre una soglia prestabilita (ad esempio 5 punti percentuali), evitando aggiustamenti inutili per piccole oscillazioni.</li><li><strong>Ribilanciamento con i nuovi versamenti</strong> — invece di vendere, si indirizzano i versamenti futuri verso l''asset class rimasta indietro, un modo per riportare le proporzioni in linea senza generare una vendita (e quindi senza un evento fiscale imponibile).</li></ul>',
    '<ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Ribilanciamento a calendario</strong> — un controllo a intervalli fissi (ad esempio una volta l''anno), indipendentemente da quanto si sono mosse le percentuali.</li><li><strong>Ribilanciamento a soglia</strong> — si interviene solo quando una asset class si discosta dal target oltre una soglia prestabilita (ad esempio 5 punti percentuali), evitando aggiustamenti inutili per piccole oscillazioni.</li><li><strong>Ribilanciamento con i nuovi versamenti</strong> — invece di vendere, si indirizzano i versamenti futuri verso l''asset class rimasta indietro, un modo per riportare le proporzioni in linea senza generare una vendita (e quindi senza un evento fiscale imponibile).</li></ul><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Esempio: portafoglio 70/30 da 10.000 euro (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5"></th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Azioni</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Obbligazioni</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">%</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Partenza</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">7.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">3.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">70/30</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Dopo un anno, azioni +50%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">10.500</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">3.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">78/22</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Ribilanciato vendendo azioni</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">9.450</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">4.050</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">70/30</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Ribilanciato con nuovi versamenti</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">10.500</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">4.500</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">70/30</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Vendendo sposti 1.050 euro dalle azioni alle obbligazioni. Con i nuovi versamenti servono 1.500 euro in obbligazioni, senza vendere nulla e senza tasse.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'ribilanciamento-portafoglio-cosa-e-perche' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Più lunga è la scadenza, più il prezzo reagisce ai tassi: un BTP a trent''anni può perdere molto valore in un periodo di rialzo dei tassi, anche se lo Stato continua a pagare regolarmente. Se lo tieni fino a scadenza ricevi comunque il valore nominale; il rischio diventa concreto se devi vendere prima.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Più lunga è la scadenza, più il prezzo reagisce ai tassi: un BTP a trent''anni può perdere molto valore in un periodo di rialzo dei tassi, anche se lo Stato continua a pagare regolarmente. Se lo tieni fino a scadenza ricevi comunque il valore nominale; il rischio diventa concreto se devi vendere prima.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Se i tassi salgono dal 3% al 4%: prezzo di un BTP con cedola 3%</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5"></th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Nuovo prezzo</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Variazione</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">BTP a 2 anni</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">98,10</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">−1,9%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">BTP a 10 anni</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">91,82</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">−8,2%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">BTP a 30 anni</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">82,62</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">−17,4%</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Prezzo per 100 euro di valore nominale, comprato a 100. Cedole semestrali, valori lordi. Tenendolo fino a scadenza ricevi comunque 100.</p></figure>'),
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il dato da guardare non è la cedola ma il <strong>rendimento a scadenza</strong>, che tiene conto anche del prezzo a cui compri. Un BTP con cedola del 2% comprato a 90 rende di più di quanto dica la cedola, perché a scadenza ti verranno restituiti 100.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il dato da guardare non è la cedola ma il <strong>rendimento a scadenza</strong>, che tiene conto anche del prezzo a cui compri. Un BTP con cedola del 2% comprato a 90 rende di più di quanto dica la cedola, perché a scadenza ti verranno restituiti 100.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">BTP con cedola 2% e 5 anni alla scadenza: il prezzo cambia il rendimento</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Prezzo di acquisto</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Cedola</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Rendimento a scadenza</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">90</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">2%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">4,24%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">100</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">2%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">2,00%</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">105</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">2%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">0,97%</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Rendimento lordo annuo, cedole semestrali. Sopra 100 rendi meno della cedola, sotto 100 di più.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'btp-titoli-di-stato-come-funzionano' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Sia gli interessi del conto deposito sia i guadagni degli ETF monetari sono tassati al <strong>26%</strong>, e su entrambi si applica l''imposta di bollo dello 0,2% annuo. C''è però una differenza: i guadagni degli ETF sono redditi di capitale e non possono compensare eventuali minusvalenze accumulate su altri investimenti. Trovi i dettagli nella guida alla <a href="/news/tassazione-investimenti-etf-azioni-italia" class="text-accent hover:underline font-medium">tassazione degli investimenti</a>.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Sia gli interessi del conto deposito sia i guadagni degli ETF monetari sono tassati al <strong>26%</strong>, e su entrambi si applica l''imposta di bollo dello 0,2% annuo. C''è però una differenza: i guadagni degli ETF sono redditi di capitale e non possono compensare eventuali minusvalenze accumulate su altri investimenti. Trovi i dettagli nella guida alla <a href="/news/tassazione-investimenti-etf-azioni-italia" class="text-accent hover:underline font-medium">tassazione degli investimenti</a>.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">10.000 euro per un anno, tasso del 3% (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5"></th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Conto deposito vincolato</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">ETF monetario</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Rendimento lordo</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">300</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">290</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Tasse (26%)</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">−78</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">−75</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Imposta di bollo (0,2%)</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">−20</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">−20</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5 font-semibold text-gray-900">Netto</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono font-semibold text-gray-900">202</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono font-semibold text-gray-900">195</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Esempio con lo stesso tasso per entrambi; l''ETF ha un TER dello 0,10%. Commissioni del broker escluse. Nella realtà il rendimento dell''ETF segue i tassi BCE giorno per giorno.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'etf-monetari-o-conto-deposito' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il rovescio della medaglia è che in circa un caso su tre il PAC ha fatto meglio, ed è proprio il caso che fa più paura: investire tutto il giorno prima di un forte ribasso.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il rovescio della medaglia è che in circa un caso su tre il PAC ha fatto meglio, ed è proprio il caso che fa più paura: investire tutto il giorno prima di un forte ribasso.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">12.000 euro: tutto subito o 1.000 al mese, valore dopo un anno (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5">Scenario</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">PIC</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">PAC</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Il mercato sale del 12%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">13.440</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">12.753</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Scende del 20% e poi recupera</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">12.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">13.392</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Scende del 20% e resta giù</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">9.600</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">10.612</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Scenari di esempio con prezzi che si muovono in modo regolare. Il PIC vince quando il mercato sale, il PAC quando scende; se scende e poi recupera, il PAC ha comprato più quote a prezzo basso.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'pac-o-pic-investire-tutto-subito-o-a-rate' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Prudente</strong>: circa 30% azioni, 60% obbligazioni, 10% liquidità. Oscillazioni contenute, crescita più lenta.</li><li><strong>Dinamico</strong>: circa 80% azioni, 20% obbligazioni. Oscillazioni ampie, potenziale di crescita più alto su orizzonti lunghi.</li></ul>',
    '<ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Prudente</strong>: circa 30% azioni, 60% obbligazioni, 10% liquidità. Oscillazioni contenute, crescita più lenta.</li><li><strong>Dinamico</strong>: circa 80% azioni, 20% obbligazioni. Oscillazioni ampie, potenziale di crescita più alto su orizzonti lunghi.</li></ul><figure class="my-6 rounded-xl border border-border bg-white p-5"><figcaption class="mb-4 text-sm font-semibold text-gray-900">Se le azioni perdono il 30%, quanto perde il portafoglio</figcaption><div class="space-y-3"><div><div class="mb-1 flex justify-between gap-3 text-sm"><span class="text-gray-700">Prudente: 30% azioni</span><span class="whitespace-nowrap font-mono text-gray-900">−9%</span></div><div class="h-2.5 rounded-full bg-gray-100"><div class="h-2.5 rounded-full bg-income" style="width:30.0%"></div></div></div><div><div class="mb-1 flex justify-between gap-3 text-sm"><span class="text-gray-700">Dinamico: 80% azioni</span><span class="whitespace-nowrap font-mono text-gray-900">−24%</span></div><div class="h-2.5 rounded-full bg-gray-100"><div class="h-2.5 rounded-full bg-loan" style="width:80.0%"></div></div></div><div><div class="mb-1 flex justify-between gap-3 text-sm"><span class="text-gray-700">Tutto in azioni</span><span class="whitespace-nowrap font-mono text-gray-900">−30%</span></div><div class="h-2.5 rounded-full bg-gray-100"><div class="h-2.5 rounded-full bg-expense" style="width:100.0%"></div></div></div></div><p class="mt-4 text-xs text-muted">Per semplicità obbligazioni e liquidità restano ferme. Nella realtà possono salire o scendere anche loro.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'asset-allocation-cos-e-come-sceglierla' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il <strong>massimo drawdown</strong> è la perdita più ampia registrata in un periodo, misurata dal punto più alto al punto più basso successivo. Se un investimento è salito fino a 100 e poi è sceso a 60 prima di riprendersi, il suo max drawdown è del 40%.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il <strong>massimo drawdown</strong> è la perdita più ampia registrata in un periodo, misurata dal punto più alto al punto più basso successivo. Se un investimento è salito fino a 100 e poi è sceso a 60 prima di riprendersi, il suo max drawdown è del 40%.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">Due investimenti da 100 euro, stesso risultato dopo 5 anni</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5"></th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Investimento A</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Investimento B</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">1° anno</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">108 (+8%)</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">125 (+25%)</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">2° anno</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">117 (+8%)</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">100 (−20%)</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">3° anno</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">126 (+8%)</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">130 (+30%)</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">4° anno</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">136 (+8%)</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">110 (−15%)</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">5° anno</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">147 (+8%)</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">147 (+33%)</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Entrambi arrivano a circa 147 euro, cioè l''8% medio annuo. A non ha mai perso; B ha un max drawdown del 20% (da 125 a 100 nel secondo anno) e una volatilità molto più alta.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'volatilita-e-max-drawdown-misurare-il-rischio' AND body NOT LIKE '%<figure%';

UPDATE news_articles SET body = REPLACE(body,
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Nel giorno di stacco il prezzo dell''azione scende, in linea di massima, dell''importo del dividendo: quel valore esce dall''azienda e arriva a te. Il tuo patrimonio complessivo non cambia, cambia la forma: una parte passa dal titolo alla liquidità. Per misurare correttamente un investimento serve quindi il <a href="/news/rendimento-totale-vs-cagr-come-leggere-la-performance" class="text-accent hover:underline font-medium">rendimento totale</a>, che somma andamento del prezzo e dividendi.</p>',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Nel giorno di stacco il prezzo dell''azione scende, in linea di massima, dell''importo del dividendo: quel valore esce dall''azienda e arriva a te. Il tuo patrimonio complessivo non cambia, cambia la forma: una parte passa dal titolo alla liquidità. Per misurare correttamente un investimento serve quindi il <a href="/news/rendimento-totale-vs-cagr-come-leggere-la-performance" class="text-accent hover:underline font-medium">rendimento totale</a>, che somma andamento del prezzo e dividendi.</p><figure class="my-6"><figcaption class="mb-2 text-sm font-semibold text-gray-900">100 azioni da 50 euro, dividendo di 1 euro per azione (importi in euro)</figcaption><div class="overflow-x-auto rounded-xl border border-border bg-white"><table class="w-full text-left text-[13px] text-gray-700 sm:text-sm"><thead class="bg-gray-50 text-[11px] uppercase tracking-wide text-muted"><tr><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5"></th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Prima dello stacco</th><th class="px-3 py-2 font-semibold sm:px-4 sm:py-2.5 text-right">Dopo lo stacco</th></tr></thead><tbody><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Valore delle azioni</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">5.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">4.900</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5">Dividendo incassato, netto 26%</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">—</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono">74</td></tr><tr class="border-t border-border"><td class="px-3 py-2 sm:px-4 sm:py-2.5 font-semibold text-gray-900">Totale</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono font-semibold text-gray-900">5.000</td><td class="px-3 py-2 sm:px-4 sm:py-2.5 whitespace-nowrap text-right font-mono font-semibold text-gray-900">4.974</td></tr></tbody></table></div><p class="mt-2 text-xs text-muted">Il prezzo scende all''incirca dell''importo del dividendo. Il patrimonio non cresce: cambia forma, e la parte incassata paga subito le tasse.</p></figure>'),
    updated_at = NOW()
WHERE slug = 'dividendi-come-funzionano-e-come-sono-tassati' AND body NOT LIKE '%<figure%';
